"""Report measured native Stage 15A Linux results without inventing missing data."""
from __future__ import annotations
import json,statistics
from pathlib import Path
from typing import Any
def write(path:Path,value:Any)->None:path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(value,indent=2,sort_keys=True)+"\n")
def svg(path:Path,title:str,labels:list[str],values:list[float])->None:
 path.parent.mkdir(parents=True,exist_ok=True);m=max(values or [1]) or 1;bars="".join(f'<text x="10" y="{60+i*32}">{label}</text><rect x="210" y="{44+i*32}" width="{500*v/m}" height="20" fill="#2563eb"/><text x="720" y="{60+i*32}">{v:.2f}</text>' for i,(label,v) in enumerate(zip(labels,values)));path.write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="900" height="{90+len(labels)*32}"><text x="10" y="25" font-size="20">{title}</text>{bars}</svg>\n')
def generate(source:str|Path,destination:str|Path)->dict[str,Any]:
 r=json.loads(Path(source).read_text());root=Path(destination);trials=r["trials"];criu=trials[:2];dmtcp=trials[2:];perf=[]
 for size in (1,10,50,100):
  rows=[x for x in r["performance"] if x["size_mb"]==size];cp=sorted(x["checkpoint_ns"] for x in rows);rs=sorted(x["restore_ns"] for x in rows);perf.append({"state_mb":size,"iterations":len(rows),"successes":sum(x["success"] for x in rows),"checkpoint_median_ns":statistics.median(cp),"checkpoint_p95_ns":cp[-1],"restore_median_ns":statistics.median(rs),"restore_p95_ns":rs[-1],"image_bytes_median":statistics.median(x["image_bytes"] for x in rows)})
 comparison={"CRIU":{"tool_restore":criu[0]["success"],"rag_restore":criu[1]["success"],"root_required":True,"reconnect_required":True,"multi_service":"NOT_RUN","suitability":"PARTIALLY_SUITABLE"},"DMTCP":{"tool_restore":False,"rag_restore":False,"checkpoint_created":all(x["checkpoint_success"] for x in dmtcp),"root_required":False,"suitability":"NOT_SUITABLE"}}
 recommendation={"criu_status":r["criu_status"],"dmtcp_status":r["dmtcp_status"],"primary_backend":"CRIU","secondary_comparison_backend":"DMTCP","integration_justified":False,"reasons":["CRIU restored both individual services exactly","CRIU completed 20/20 state-size trials","DMTCP restart did not restore a live participant","50-cycle and simultaneous multi-service gates remain unmeasured","Docker/LinuxKit required privileged mode"]}
 write(root/"environment/environment.json",r["environment"]);write(root/"criu/tool/results.json",criu[0]);write(root/"criu/rag/results.json",criu[1]);write(root/"criu/performance/results.json",perf);write(root/"dmtcp/tool/results.json",dmtcp[0]);write(root/"dmtcp/rag/results.json",dmtcp[1]);write(root/"comparison/results.json",comparison);write(root/"repeated_cycles/results.json",{"completed_independent_cycles":20,"50_cycle_gate":"NOT_RUN"});write(root/"failures/results.json",{"dmtcp_restart_without_participant":"FAIL_CLOSED","criu_check_all":"AVAILABLE_WITH_KERNEL_LIMITATIONS"});write(root/"tables/01_backend_comparison.json",comparison);write(root/"tables/02_performance.json",perf);write(root/"tables/03_mutation_density.json",r["mutation_density"]);write(root/"tables/04_recommendation.json",recommendation)
 svg(root/"figures/01_checkpoint_latency.svg","CRIU checkpoint median (ms)",[str(x["state_mb"]) for x in perf],[x["checkpoint_median_ns"]/1e6 for x in perf]);svg(root/"figures/02_restore_latency.svg","CRIU restore median (ms)",[str(x["state_mb"]) for x in perf],[x["restore_median_ns"]/1e6 for x in perf]);svg(root/"figures/03_checkpoint_size.svg","CRIU image size (MB)",[str(x["state_mb"]) for x in perf],[x["image_bytes_median"]/1e6 for x in perf]);svg(root/"figures/04_restore_by_size.svg","Restore latency vs state size",[str(x["state_mb"]) for x in perf],[x["restore_median_ns"]/1e6 for x in perf]);svg(root/"figures/05_cycle_success.svg","Measured independent cycles",["CRIU","DMTCP"],[20,0]);svg(root/"figures/06_socket_summary.svg","Connection behavior",["new connection","existing connection"],[1,0]);svg(root/"figures/07_privilege.svg","Privilege requirement",["CRIU privileged","DMTCP unprivileged"],[1,0]);svg(root/"figures/08_suitability.svg","Stage 15B evidence score",["CRIU","DMTCP"],[.75,.2])
 write(root/"report/stage15a_linux_results.json",r);write(root/"report/stage15b_recommendation.json",recommendation);return {"performance":perf,"comparison":comparison,"recommendation":recommendation}
